import { getPlanLimits } from "@/config/plan-limits";
import type { BillingInterval, PlanId } from "@/types/billing";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Months a period of the given interval spans. */
export function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/**
 * Same day-of-month and time of day `months` later (UTC), or the last day of
 * the target month when it has no such day (31 Jan + 1 month → 28/29 Feb).
 */
export function addMonthsClamped(from: Date, months: number): Date {
  const monthIndex = from.getUTCMonth() + months;
  const year = from.getUTCFullYear() + Math.floor(monthIndex / 12);
  const month = ((monthIndex % 12) + 12) % 12;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();

  const result = new Date(from.getTime());
  result.setUTCFullYear(year, month, Math.min(from.getUTCDate(), lastDay));
  return result;
}

/** End of the period that starts at `start`. */
export function periodEndFor(start: Date, interval: BillingInterval): Date {
  return addMonthsClamped(start, monthsInInterval(interval));
}

/** The full charge for one period of `plan`, in cents. */
export function periodChargeCents(
  plan: PlanId,
  seats: number,
  interval: BillingInterval,
): number {
  return (
    getPlanLimits(plan).priceCentsPerSeatMonthly *
    seats *
    monthsInInterval(interval)
  );
}

/**
 * Scales a full-period amount by the days left in the period, rounded down to
 * whole cents. Days left are whole or started days from `now` to the period
 * end (none once it has been reached); days in the period are the rounded
 * whole days between start and end, at least one.
 */
export function prorateCents(
  fullCents: number,
  now: Date,
  periodStart: Date,
  periodEnd: Date,
): number {
  const msLeft = periodEnd.getTime() - now.getTime();
  if (msLeft <= 0) return 0;

  const daysLeft = Math.ceil(msLeft / MS_PER_DAY);
  const daysInPeriod = Math.max(
    1,
    Math.round((periodEnd.getTime() - periodStart.getTime()) / MS_PER_DAY),
  );

  return Math.floor((fullCents * daysLeft) / daysInPeriod);
}

