/**
 * Renews subscriptions period by period, invoices every renewed paid period
 * and ends cancellations on their date.
 *
 * Must call (do not reimplement): emit, getPlanLimits
 */
import { periodChargeCents, periodEndFor } from "@/lib/billing-period";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { publishInvoices } from "@/server/services/billing-service";
import { envelope } from "@/server/services/_support";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { InvoiceDraft } from "@/server/repositories/subscription-repository";
import type { JobResult } from "@/server/jobs/types";
import type { Subscription } from "@/types/billing";

const logger = createLogger("billing-renewal-job");

/**
 * One pass over every live workspace's subscription.
 *
 * Replay-safe by construction: a renewal leaves the period end after `now`
 * and a finished cancellation leaves an `active` free plan, so a second run at
 * the same instant selects nothing — and the write itself is guarded against
 * the row having moved since it was read.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const subscriptions = await subscriptionRepo.listRenewableSubscriptions();

    for (const subscription of subscriptions) {
      try {
        const changed = await processSubscription(subscription, now);
        if (changed) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId: subscription.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function processSubscription(
  subscription: Subscription,
  now: Date,
): Promise<boolean> {
  if (subscription.status === "canceled") {
    return endCancellation(subscription, now);
  }
  if (subscription.status === "active") {
    return renew(subscription, now);
  }
  return false;
}

/**
 * Rolls an active subscription forward one interval at a time until its period
 * end lies after `now`, invoicing each period of a paid plan in full.
 */
async function renew(subscription: Subscription, now: Date): Promise<boolean> {
  const periods = periodsUntil(
