    const feb = addMonthsClamped(new Date("2026-01-31T10:30:00.000Z"), 1);
    expect(feb.toISOString()).toBe("2026-02-28T10:30:00.000Z");
    expect(addMonthsClamped(feb, 1).toISOString()).toBe("2026-03-28T10:30:00.000Z");
  });

  it("moves a leap day to 28 February a year on", () => {
    expect(
      addMonthsClamped(new Date("2024-02-29T00:00:00.000Z"), 12).toISOString(),
    ).toBe("2025-02-28T00:00:00.000Z");
  });

  it("counts started days when prorating and rounds down", () => {
    const start = new Date("2026-06-01T00:00:00.000Z");
    const end = new Date("2026-07-01T00:00:00.000Z");
    const now = new Date("2026-06-16T02:00:00.000Z"); // 14 days 22 hours left
    expect(prorateCents(3000, now, start, end)).toBe(1500);
